Object.assign(SNIP,{"post_offline": "vector<vector<pair<int, int>>> hoi(n + 1);   // hoi[U]: các (V, số thứ tự truy vấn)\nfor (int k = 0; k < Q; k++) {\n    int U, V;\n    cin >> U >> V;\n    hoi[U].push_back({V, k});\n}\nvector<long long> acc(n + 1, 0), kq(Q);\nfor (int U = n; U >= 1; U--) {\n    int mn = INT_MAX, mx = 0;\n    long long row = 0;\n    for (int V = U; V <= n; V++) {\n        mn = min(mn, f[V]);\n        mx = max(mx, l[V]);\n        if (mn >= U && mx <= V) row++;       // [U, V] toàn vẹn\n        acc[V] += row;                      // acc[V]: số đoạn tốt có L >= U, R <= V\n    }\n    for (auto& h : hoi[U]) kq[h.second] = acc[h.first];\n}\nfor (int k = 0; k < Q; k++) cout << kq[k] << \"\\n\";", "light_cong_thuc": "// c1[i], c2[i]: số bóng vàng, số bóng đỏ trong i bóng đầu (cộng dồn)\nwhile (Q--) {\n    int L, R;\n    cin >> L >> R;\n    int a = c1[R] - c1[L - 1], b = c2[R] - c2[L - 1];\n    if ((a - b) % 3 != 0) cout << -1 << \"\\n\";          // bất biến: tổng mod 3\n    else cout << max(a, b) - abs(a - b) / 3 << \"\\n\";\n}", "post_trau": "while (Q--) {\n    int U, V;\n    cin >> U >> V;\n    long long c = 0;\n    for (int L = U; L <= V; L++) {\n        int mn = INT_MAX, mx = 0;          // min first, max last của đoạn [L, R]\n        for (int R = L; R <= V; R++) {\n            mn = min(mn, f[R]);\n            mx = max(mx, l[R]);\n            if (mn >= L && mx <= R) c++;\n        }\n    }\n    cout << c << \"\\n\";\n}", "light_bfs": "// trạng thái đoạn: số cơ số 3, d[x] = số thao tác ít nhất để tới x\nvector<int> d(pw3[n], -1);\nqueue<int> q;\nd[batDau] = 0;\nq.push(batDau);\nwhile (!q.empty()) {\n    int u = q.front();\n    q.pop();\n    for (int i = 0; i < n; i++)          // bóng xoay thuận\n        for (int j = 0; j < n; j++) {    // bóng xoay ngược, khác i\n            if (i == j) continue;\n            int ci = u / pw3[i] % 3, cj = u / pw3[j] % 3;\n            int v = u + ((ci + 1) % 3 - ci) * pw3[i] + ((cj + 2) % 3 - cj) * pw3[j];\n            if (d[v] < 0) { d[v] = d[u] + 1; q.push(v); }\n        }\n}\ncout << d[0] << \"\\n\";                    // -1 nếu không tới được"});PRESET_NOTES["l26"]={"Ví dụ: Rẽ nhánh theo subtask": "Cặp có tổng chia hết cho 3: (1, 2), (1, 5), (2, 4), (4, 5) — 4 cặp. Với n nhỏ, nhánh trâu chạy; với n lớn, nhánh đếm số dư chạy. Hai nhánh độc lập: một nhánh sai không làm hỏng điểm của nhánh kia.", "Ví dụ: Ước lượng trước khi code": "Với ngưỡng khoảng 10⁸ phép tính mỗi giây: O(n²) kịp ở n = 1000 và n = 10⁴, không kịp ở n = 10⁵. Tính nhẩm như thế này cho từng dòng subtask trước khi viết code."};EX_HINTS["l26"]=[["Lời giải trâu O(n²) lấy được subtask 1.", "aᵢ + aⱼ chia hết cho k ⇔ (aᵢ mod k) + (aⱼ mod k) chia hết cho k. Đếm số dư của các số đứng trước bằng mảng cnt[k].", "Số dư bù của r là (k − r) mod k (với r = 0 thì bù là 0). Số cặp tới 5·10¹¹: long long."], ["Trâu O(n²) lấy subtask 1.", "Tổng đoạn (l, r] = p[r] − p[l] với l ≤ r − L. Với mỗi r, cần p[l] nhỏ nhất trong p[0 .. r − L].", "Giữ mn = min p[0 .. r − L] khi r tăng: O(n)."], ["Có số âm nên không dùng được hai con trỏ (Bài 16).", "Đoạn (l, r] có tổng S ⇔ p[l] = p[r] − S. Đếm số tiền tố trước đó bằng p[r] − S bằng map.", "Khởi tạo dem[0] = 1 (tiền tố rỗng). Kết quả tới n²/2: long long."], ["Mỗi thao tác +1 một bóng, −1 một bóng khác: tổng các trạng thái theo mod 3 có đổi không?", "Đáp án chỉ phụ thuộc số bóng vàng và số bóng đỏ trong đoạn. Viết BFS cho đoạn ngắn để quan sát quy luật."], ["Đoạn [L, R] toàn vẹn ⇔ mọi vị trí i trong đoạn có vị trí xuất hiện đầu tiên và cuối cùng của A[i] đều nằm trong đoạn.", "Tính sẵn cho mọi đoạn một lần (O(N²)), rồi đếm các đoạn có L ≥ U, R ≤ V bằng cộng dồn."]];
