const PR26=[{label:"Ví dụ: Rẽ nhánh theo subtask",input:"5 3\n1 2 3 4 5",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CAPCHIA.INP\", \"r\")) {\n        freopen(\"CAPCHIA.INP\", \"r\", stdin);\n        freopen(\"CAPCHIA.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long k;\n    cin >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    long long dem = 0;\n    if (n <= 1000) {                        // subtask 1: trâu O(n²), chắc chắn đúng\n        for (int i = 0; i < n; i++)\n            for (int j = i + 1; j < n; j++)\n                if ((a[i] + a[j]) % k == 0) dem++;\n    } else {                                // subtask lớn: đếm theo số dư (k ≤ 10^6)\n        vector<long long> cnt(k, 0);\n        for (long long x : a) {\n            long long r = x % k;\n            dem += cnt[(k - r) % k];\n            cnt[r]++;\n        }\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","k","dem"]}]},{label:"Ví dụ: Ước lượng trước khi code",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    long long cacN[] = {1000, 100000, 1000000};\n    for (long long n : cacN) {\n        long long n2 = n * n;\n        cout << \"n = \" << n << \": n^2 = \" << n2\n             << (n2 <= 100000000 ? \" (kip)\" : \" (qua cham)\") << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["n","n2"]}]}];
